# ─────────────────────────────────────────────
# HELPER FUNCTIONS
# ─────────────────────────────────────────────
def _ema(values: list, period: int) -> float:
    """EMA sederhana."""
    if len(values) < period:
        return sum(values) / len(values)
    k = 2 / (period + 1)
    ema = sum(values[:period]) / period
    for v in values[period:]:
        ema = v * k + ema * (1-k)
    return ema

def _atr(highs: list, lows: list, closes: list, period: int = 14) -> float:
    """Average True Range - ukuran volatilitas."""
    if len(closes) < period + 1:
        return (max(highs[-5:])-min(lows[-5:])) / 2 if highs else 0
    trs = []
    for i in range(1, min(period + 1, len(closes))):
        tr = max(
            highs[-i]-lows[-i],
            abs(highs[-i]-closes[-i-1]),
            abs(lows[-i] -closes[-i-1]),
        )
        trs.append(tr)
    return sum(trs) / len(trs) if trs else 0

def _swing_lows(lows: list, window: int = 3) -> list:
    """Cari swing low dari data harga."""
    result = []
    for i in range(window, len(lows)-window):
        if lows[i] == min(lows[i-window: i + window + 1]):
            result.append((i, lows[i]))
    return result

def _swing_highs(highs: list, window: int = 3) -> list:
    """Cari swing high dari data harga."""
    result = []
    for i in range(window, len(highs)-window):
        if highs[i] == max(highs[i-window: i + window + 1]):
            result.append((i, highs[i]))
    return result

def _clamp(val, lo=0, hi=100) -> int:
    return int(max(lo, min(hi, val)))


# ─────────────────────────────────────────────
# KOMPONEN 1 - TEKNIKAL SCORE (0–100)
# ─────────────────────────────────────────────
def _score_teknikal(pd: PriceData) -> tuple:
    """
    Scoring berbasis MnM Strategy+:
   -EMA alignment (13/21/50/200)
   -Price vs EMA positions
   -Struktur HH/HL atau LL/LH
   -Candle momentum
    Returns (score 0–100, signals list)
    """
    c = pd.closes
    h = pd.highs
    l = pd.lows
    signals = []
    score = 50  # baseline netral

    if len(c) < 5:
        return 50, ["Data teknikal tidak cukup"]

    price = c[-1]

    # ── EMA Calculation ──
    ema13  = _ema(c, 13)  if len(c) >= 13  else _ema(c, len(c))
    ema21  = _ema(c, 21)  if len(c) >= 21  else _ema(c, len(c))
    ema50  = _ema(c, 50)  if len(c) >= 50  else _ema(c, len(c))
    ema200 = _ema(c, 200) if len(c) >= 200 else _ema(c, len(c))

    # ── EMA Alignment Score ──
    bullish_ema = 0
    if price > ema13:  bullish_ema += 1
    if price > ema21:  bullish_ema += 1
    if price > ema50:  bullish_ema += 1
    if price > ema200: bullish_ema += 1
    if ema13 > ema21:  bullish_ema += 1
    if ema21 > ema50:  bullish_ema += 1

    # EMA alignment: 0–6 → mapped ke -20 to +30
    ema_contribution = (bullish_ema / 6) * 50-15
    score += ema_contribution

    if bullish_ema >= 5:
        signals.append("✅ EMA bullish alignment penuh (price > EMA13/21/50/200)")
    elif bullish_ema >= 3:
        signals.append("🟡 EMA alignment parsial")
    else:
        signals.append("🔴 EMA bearish - harga di bawah EMA kunci")

    # ── Struktur HH/HL vs LL/LH ──
    if len(c) >= 10:
        recent_highs = h[-10:]
        recent_lows  = l[-10:]
        # HH: high terbaru > high 5 hari lalu
        if recent_highs[-1] > recent_highs[-6] and recent_lows[-1] > recent_lows[-6]:
            score += 10
            signals.append("✅ Struktur HH/HL - uptrend valid")
        elif recent_highs[-1] < recent_highs[-6] and recent_lows[-1] < recent_lows[-6]:
            score -= 10
            signals.append("🔴 Struktur LL/LH - downtrend aktif")

    # ── Golden/Death Cross ──
    if len(c) >= 55:
        ema50_prev = _ema(c[:-1], 50)
        ema200_prev = _ema(c[:-5], 200) if len(c) >= 205 else ema200
        if ema50 > ema200 and ema50_prev <= ema200_prev:
            score += 15
            signals.append("🌟 GOLDEN CROSS EMA50/200 - sinyal bullish mayor")
        elif ema50 < ema200 and ema50_prev >= ema200_prev:
            score -= 15
            signals.append("💀 DEATH CROSS EMA50/200 - sinyal bearish mayor")

    # ── Candle Momentum (3 hari terakhir) ──
    if len(c) >= 4:
        bodies = [abs(c[-i]-c[-i-1]) for i in range(1, 4)]
        avg_body = sum(bodies) / 3
        last_body = abs(c[-1]-c[-2])
        # Candle besar = momentum kuat
        if last_body > avg_body * 1.5 and c[-1] > c[-2]:
            score += 8
            signals.append("⚡ Candle momentum bullish kuat")
        elif last_body > avg_body * 1.5 and c[-1] < c[-2]:
            score -= 8
            signals.append("⚡ Candle momentum bearish kuat")

    # ── Proximity ke EMA21 (area entry ideal MnM) ──
    dist_ema21 = abs(price-ema21) / ema21 * 100
    if dist_ema21 <= 1.5 and price >= ema21:
        score += 7
        signals.append("🎯 Harga di atas EMA21 (zona entry MnM)")
    elif dist_ema21 <= 3.0 and price >= ema21 * 0.98:
        score += 4
        signals.append("🟡 Harga mendekati EMA21")

    return _clamp(score), signals


# ─────────────────────────────────────────────
# KOMPONEN 2 - VOLUME SCORE (0–100)
# ─────────────────────────────────────────────
def _score_volume(pd: PriceData) -> tuple:
    """
    Volume Intelligence (sesuai GROQ_SYSTEM_PROMPT SIGMA):
   -Spike detection vs avg 20 hari
   -Price-Volume Divergence
   -Dry-up detection (akumulasi stealth)
   -Absorpsi di zona supply/demand
    """
    c = pd.closes
    v = pd.volumes
    h = pd.highs
    l = pd.lows
    signals = []
    score = 50

    if len(v) < 5:
        return 50, ["Data volume tidak cukup"]

    avg20 = sum(v[-20:]) / min(len(v), 20)
    avg5  = sum(v[-5:])  / min(len(v), 5)
    last_vol  = v[-1]
    last_price = c[-1]
    prev_price = c[-2] if len(c) >= 2 else last_price

    spike_ratio = last_vol / avg20 if avg20 > 0 else 1

    # ── Volume Spike Classification ──
    if spike_ratio >= 10:
        signals.append(f"🔴 VOLUME EKSTREM {spike_ratio:.1f}x avg - event besar, cek berita!")
        # Ekstrem: bisa reversal atau katalis besar - netral dulu, tunggu konfirmasi
        score += 0
    elif spike_ratio >= 5:
        signals.append(f"🟠 Volume sangat tinggi {spike_ratio:.1f}x avg - institusi aktif")
        score += 15 if last_price > prev_price else -5
    elif spike_ratio >= 2:
        signals.append(f"🟡 Volume spike {spike_ratio:.1f}x avg")
        score += 10 if last_price > prev_price else -3

    # ── Price-Volume Divergence (5 hari) ──
    if len(c) >= 6 and len(v) >= 6:
        price_chg_5d = (c[-1]-c[-6]) / c[-6] * 100 if c[-6] > 0 else 0
        vol_avg_5d_old = sum(v[-11:-6]) / 5 if len(v) >= 11 else avg20
        vol_avg_5d_new = sum(v[-5:])    / 5
        vol_chg_pct = (vol_avg_5d_new-vol_avg_5d_old) / vol_avg_5d_old * 100 if vol_avg_5d_old > 0 else 0

        if price_chg_5d > 2 and vol_chg_pct < -20:
            score -= 15
            signals.append("⚠️ DIVERGENSI: Harga naik tapi volume TURUN - momentum lemah")
        elif price_chg_5d > 2 and vol_chg_pct > 20:
            score += 18
            signals.append("✅ Harga naik + volume naik - momentum KUAT")
        elif price_chg_5d < -2 and vol_chg_pct < -20:
            score += 8
            signals.append("🔵 Seller exhaustion - volume turun saat harga turun")
        elif price_chg_5d < -2 and vol_chg_pct > 20:
            score -= 12
            signals.append("🔴 Distribusi massal - harga turun + volume spike")

    # ── Volume Dry-Up Detection (akumulasi stealth) ──
    dry_up = avg5 < (avg20 * 0.45)
    if dry_up:
        score += 12
        signals.append("🔵 Volume DRY-UP - potensi akumulasi stealth sebelum breakout")

    # ── Candle-Body vs Volume Konviksi ──
    if len(c) >= 3 and len(h) >= 3 and len(l) >= 3:
        candle_body = abs(c[-1]-c[-2])
        candle_range = h[-1]-l[-1]
        body_ratio = candle_body / candle_range if candle_range > 0 else 0.5

        if body_ratio > 0.7 and spike_ratio >= 1.5 and last_price > prev_price:
            score += 12
            signals.append("✅ Candle besar + volume tinggi - konviksi KUAT bullish")
        elif body_ratio < 0.3 and spike_ratio >= 2:
            score -= 5
            signals.append("⚠️ Candle kecil + volume tinggi - pertempuran BUY/SELL, tunggu resolusi")
        elif body_ratio > 0.7 and spike_ratio < 0.5:
            score -= 8
            signals.append("⚠️ Candle besar tapi volume rendah - potensi TRAP/manipulasi")

    return _clamp(score), signals


# ─────────────────────────────────────────────
# KOMPONEN 3 - BANDAR SCORE (0–100)
# ─────────────────────────────────────────────
def _score_bandar(pd: PriceData) -> tuple:
    """
    Deteksi akumulasi/distribusi bandar dari price & volume behavior.
    Tanpa broker data real-time → gunakan proxy: clustering volume di price levels,
    quiet accumulation pattern, dan distribusi di resistance.

    IDX Rule (counter-intuitive):
   -Volume spike kecil tapi sustained di low = AKUMULASI
   -Volume spike besar di high = DISTRIBUSI
    """
    c = pd.closes
    v = pd.volumes
    h = pd.highs
    l = pd.lows
    signals = []
    score = 50

    if len(c) < 10:
        return 50, ["Data tidak cukup untuk deteksi bandar"]

    avg_vol_20 = sum(v[-20:]) / min(len(v), 20)

    # ── Pattern 1: Stealth Accumulation (quiet buying at lows) ──
    # Ciri: harga sideways/turun perlahan + volume di bawah rata-rata tapi konsisten
    price_range_10d = (max(c[-10:])-min(c[-10:])) / c[-10] * 100 if c[-10] > 0 else 0
    vol_consistency = min(v[-10:]) / avg_vol_20 if avg_vol_20 > 0 else 0

    if price_range_10d < 5 and vol_consistency > 0.3:  # sideways + volume konsisten
        score += 15
        signals.append("🟢 Pola AKUMULASI STEALTH: sideways + volume konsisten - bandar mengumpulkan")

    # ── Pattern 2: High-Volume Reversal at Bottom ──
    # Volume spike besar di harga rendah = bandar absorb supply dari retail panik
    price_at_low = c[-1] <= min(c[-20:]) * 1.05  # dalam 5% dari low 20 hari
    if price_at_low and v[-1] > avg_vol_20 * 2:
        score += 20
        signals.append("🟢 ABSORPSI di LOW: volume spike di zona bawah - potensial reversal bandar")

    # ── Pattern 3: Distribution Pattern ──
    # Volume spike besar di high = bandar distribusi ke retail FOMO
    price_at_high = c[-1] >= max(c[-20:]) * 0.97  # dalam 3% dari high 20 hari
    if price_at_high and v[-1] > avg_vol_20 * 2.5:
        score -= 25
        signals.append("🔴 DISTRIBUSI di HIGH: volume ekstrem di zona atas - potensi bandar jual ke retail")

    # ── Pattern 4: Institutional Buildup (volume naik bertahap saat harga naik) ──
    if len(c) >= 15:
        vol_trend_early = sum(v[-15:-10]) / 5
        vol_trend_late  = sum(v[-5:]) / 5
        price_trend     = (c[-1]-c[-15]) / c[-15] * 100 if c[-15] > 0 else 0

        if price_trend > 5 and vol_trend_late > vol_trend_early * 1.3:
            score += 18
            signals.append("✅ INSTITUTIONAL BUILDUP: harga naik + volume bertahap meningkat")
        elif price_trend > 5 and vol_trend_late < vol_trend_early * 0.7:
            score -= 10
            signals.append("⚠️ Harga naik tapi volume trend TURUN - distribusi mungkin dimulai")

    # ── Pattern 5: Shakeout Detection ──
    # Penurunan tajam 1 hari dengan volume tinggi tapi close kembali ke atas
    if len(c) >= 3 and len(h) >= 3 and len(l) >= 3:
        intraday_drop = (l[-2]-c[-3]) / c[-3] * 100 if c[-3] > 0 else 0  # low kemarin vs close 2 hari lalu
        recovery      = (c[-1]-l[-2]) / l[-2] * 100 if l[-2] > 0 else 0    # recovery hari ini dari low kemarin
        if intraday_drop < -3 and recovery > 2 and v[-2] > avg_vol_20 * 1.5:
            score += 14
            signals.append("🟡 SHAKEOUT PATTERN: penurunan tajam diikuti recovery - bandar kumpulin di panic sell")

    # ── Pattern 6: Stop Hunt ──
    # Wick panjang ke bawah dengan body kecil = test stop loss lalu reversal
    if len(l) >= 2 and len(c) >= 2:
        wick_down = c[-2]-l[-2]  # lower wick
        body      = abs(c[-2]-c[-3]) if len(c) >= 3 else 1
        if body > 0 and wick_down > body * 2 and c[-1] > c[-2]:
            score += 10
            signals.append("🟡 STOP HUNT: wick panjang ke bawah + recovery - bandar test supply")

    return _clamp(score), signals


# ─────────────────────────────────────────────
# KOMPONEN 4 - FUNDAMENTAL SCORE (0–100)
# ─────────────────────────────────────────────
def _score_fundamental(fd: Optional[FundamentalData]) -> tuple:
    """
    Warren Buffett criteria + IDX context.
    Score tinggi = fundamental kuat, undervalue, profitable.
    """
    if fd is None:
        return 50, ["Data fundamental tidak tersedia - skor netral"]

    signals = []
    score = 50

    # ── ROE (target: >15%) ──
    if fd.roe is not None:
        roe_pct = fd.roe * 100 if fd.roe < 5 else fd.roe  # handle persen vs desimal
        if roe_pct > 20:
            score += 15
            signals.append(f"✅ ROE {roe_pct:.1f}% - sangat baik (>20%)")
        elif roe_pct > 15:
            score += 8
            signals.append(f"✅ ROE {roe_pct:.1f}% - baik (>15%)")
        elif roe_pct < 8:
            score -= 12
            signals.append(f"🔴 ROE {roe_pct:.1f}% - lemah (<8%)")

    # ── DER (target: <1x untuk non-bank) ──
    if fd.der is not None:
        if fd.der < 0.5:
            score += 10
            signals.append(f"✅ DER {fd.der:.2f}x - konservatif (rendah utang)")
        elif fd.der > 2.0:
            score -= 15
            signals.append(f"🔴 DER {fd.der:.2f}x - utang tinggi, risiko keuangan")
        elif fd.der > 1.5:
            score -= 7
            signals.append(f"⚠️ DER {fd.der:.2f}x - utang perlu diperhatikan")

    # ── PBV (target: 1x–3x ideal untuk IDX) ──
    if fd.pbv is not None:
        if 0.5 <= fd.pbv <= 2.0:
            score += 12
            signals.append(f"✅ PBV {fd.pbv:.2f}x - valuasi menarik")
        elif fd.pbv < 0.5:
            score += 6
            signals.append(f"🟡 PBV {fd.pbv:.2f}x - sangat murah (cek apakah ada masalah)")
        elif fd.pbv > 5.0:
            score -= 12
            signals.append(f"🔴 PBV {fd.pbv:.2f}x - sudah mahal")
        elif fd.pbv > 3.0:
            score -= 5
            signals.append(f"⚠️ PBV {fd.pbv:.2f}x - premium, butuh katalis kuat")

    # ── EPS Growth ──
    if fd.eps_growth is not None:
        eg_pct = fd.eps_growth * 100 if fd.eps_growth < 5 else fd.eps_growth
        if eg_pct > 20:
            score += 10
            signals.append(f"✅ EPS growth {eg_pct:.1f}% YoY - pertumbuhan kuat")
        elif eg_pct > 10:
            score += 5
        elif eg_pct < 0:
            score -= 12
            signals.append(f"🔴 EPS turun {eg_pct:.1f}% YoY - laba menyusut")

    # ── Net Margin ──
    if fd.net_margin is not None:
        nm_pct = fd.net_margin * 100 if fd.net_margin < 5 else fd.net_margin
        if nm_pct > 15:
            score += 8
            signals.append(f"✅ Net margin {nm_pct:.1f}% - profitabilitas solid")
        elif nm_pct < 3:
            score -= 8
            signals.append(f"⚠️ Net margin {nm_pct:.1f}% - sangat tipis")

    # ── Current Ratio ──
    if fd.current_ratio is not None:
        if fd.current_ratio >= 2.0:
            score += 5
        elif fd.current_ratio < 1.0:
            score -= 10
            signals.append(f"🔴 Current ratio {fd.current_ratio:.2f}x - likuiditas ketat")

    return _clamp(score), signals


# ─────────────────────────────────────────────
# KOMPONEN 5 - MOMENTUM RS SCORE (0–100)
# ─────────────────────────────────────────────
def _score_momentum_rs(pd: PriceData) -> tuple:
    """
    Relative Strength vs IHSG.
    RS > 1 = outperform → bullish kandidat
    RS < 1 = underperform → lemah vs market
    """
    c = pd.closes
    ihsg = pd.ihsg_closes
    signals = []

    if len(c) < 10:
        return 50, ["Data tidak cukup untuk RS"]

    # Internal momentum (tanpa IHSG)
    ret_5d  = (c[-1]-c[-6])  / c[-6]  * 100 if len(c) >= 6  and c[-6]  > 0 else 0
    ret_20d = (c[-1]-c[-21]) / c[-21] * 100 if len(c) >= 21 and c[-21] > 0 else 0

    score = 50
    score += ret_5d * 1.5    # 1% naik 5 hari = +1.5 poin
    score += ret_20d * 0.8   # 1% naik 20 hari = +0.8 poin

    if ret_5d > 5:
        signals.append(f"⚡ Momentum kuat: +{ret_5d:.1f}% dalam 5 hari terakhir")
    elif ret_5d < -5:
        signals.append(f"🔴 Momentum lemah: {ret_5d:.1f}% dalam 5 hari terakhir")

    # RS vs IHSG jika data tersedia
    if len(ihsg) >= 10:
        ihsg_ret_20d = (ihsg[-1]-ihsg[-21]) / ihsg[-21] * 100 if len(ihsg) >= 21 and ihsg[-21] > 0 else 0
        rs = ret_20d / ihsg_ret_20d if ihsg_ret_20d != 0 else 1.0

        if rs > 1.5:
            score += 15
            signals.append(f"✅ RS {rs:.2f}x - OUTPERFORM IHSG signifikan")
        elif rs > 1.1:
            score += 8
            signals.append(f"✅ RS {rs:.2f}x - outperform IHSG")
        elif rs < 0.7:
            score -= 15
            signals.append(f"🔴 RS {rs:.2f}x - underperform IHSG - hindari saat ini")
        elif rs < 0.9:
            score -= 7
            signals.append(f"⚠️ RS {rs:.2f}x - lebih lemah dari IHSG")

    return _clamp(score), signals


# ─────────────────────────────────────────────
# TRADE LEVEL CALCULATOR
# ─────────────────────────────────────────────
def _calc_trade_levels(pd: PriceData, zone_result=None) -> dict:
    """
    Auto-hitung entry zone, SL, TP1/2/3 dari struktur teknikal MnM.
    Prioritas: IFVG/FVG/Demand/OB Bull → Entry, Supply/OB Bear → TP.
    SL di bawah zona demand / swing low terkuat.
    """
    c = pd.closes
    h = pd.highs
    l = pd.lows

    if len(c) < 20:
        return {}

    price = c[-1]
    atr = _atr(h, l, c, 14)

    # ── Support & Resistance dari Swing ──
    s_lows  = _swing_lows(l[-50:],  window=3)
    s_highs = _swing_highs(h[-50:], window=3)

    supports    = sorted([x[1] for x in s_lows  if x[1] < price], reverse=True)
    resistances = sorted([x[1] for x in s_highs if x[1] > price])

    # ── Zone-aware Entry: prioritaskan Demand / IFVG Bull / FVG Bull / OB Bull ──
    entry_lo = None
    entry_hi = None
    sl       = None

    if zone_result is not None:
        # Kumpulkan semua zona support (demand side) di bawah atau dekat harga
        support_zones = []
        for z in (zone_result.demand + zone_result.ifvg_bull + zone_result.fvg_bull + zone_result.ob_bull):
            top = z.get("top", 0)
            bot = z.get("bot", 0)
            if bot > 0 and top > 0 and bot <= price * 1.02:  # zona di bawah atau sangat dekat harga
                support_zones.append((bot, top))

        if support_zones:
            # Ambil zona terdekat ke harga
            support_zones.sort(key=lambda x: abs(price - x[1]), reverse=False)
            best_bot, best_top = support_zones[0]
            entry_lo = _round_tick(best_bot)
            entry_hi = _round_tick(min(best_top, price))
            # SL di bawah zona support terkuat (ATR buffer)
            sl = _round_tick(best_bot - atr * 1.2)

        # TP dari Supply / OB Bear / IFVG Bear / FVG Bear di atas harga
        resistance_zones = []
        for z in (zone_result.supply + zone_result.ob_bear + zone_result.ifvg_bear + zone_result.fvg_bear):
            bot = z.get("bot", 0)
            top = z.get("top", 0)
            if bot > price:
                resistance_zones.append(bot)
        resistance_zones = sorted(resistance_zones)

        # Gabungkan dengan swing resistances
        resistances = sorted(set(resistances + resistance_zones))

    # Fallback ke swing jika zona tidak ada
    if entry_lo is None:
        nearest_support = supports[0] if supports else price - atr * 1.5
        entry_lo = _round_tick(max(nearest_support, price - atr * 0.8))
        entry_hi = _round_tick(price)

    if sl is None:
        second_support = supports[1] if len(supports) > 1 else (supports[0] - atr if supports else price - atr * 2)
        sl = _round_tick(second_support - atr * 0.5)
        sl = min(sl, entry_lo - atr)

    # Pastikan entry_lo < entry_hi dan SL < entry_lo
    if entry_hi is None or entry_hi <= entry_lo:
        entry_hi = _round_tick(entry_lo + atr * 0.5)
    sl = min(sl, entry_lo - _round_tick(atr * 0.5))

    # ── Take Profits dari resistance structure ──
    tp1 = _round_tick(resistances[0]) if resistances else _round_tick(price + atr * 2)
    tp2 = _round_tick(resistances[1]) if len(resistances) > 1 else _round_tick(tp1 + atr * 1.5)
    tp3 = _round_tick(resistances[2]) if len(resistances) > 2 else None

    # Pastikan TP > entry_hi
    tp1 = max(tp1, _round_tick(entry_hi + atr))
    tp2 = max(tp2, _round_tick(tp1 + atr))

    # ── R/R Ratio ──
    mid_entry = (entry_lo + entry_hi) / 2
    risk      = max(mid_entry - sl, atr * 0.5)
    reward    = tp1 - mid_entry
    rr        = round(reward / risk, 2) if risk > 0 else 0

    return {
        "entry_zone": (entry_lo, entry_hi),
        "sl":         sl,
        "tp1":        tp1,
        "tp2":        tp2,
        "tp3":        tp3,
        "rr_ratio":   rr,
    }


# ─────────────────────────────────────────────
# KOMPONEN 3B - BANDAR SCORE FROM BROKER SUMMARY (user input)
# ─────────────────────────────────────────────
def score_bandar_from_broker_summary(broker_text: str) -> tuple:
    """
    Parse broker summary yang diinput user (copy-paste dari RTI/Stockbit/IPOT).
    Menerapkan logika IDX yang counter-intuitive:
     -Banyak buyer broker + sedikit seller broker = DISTRIBUSI
     -Sedikit buyer broker + banyak seller broker = AKUMULASI

    Format yang didukung:
      "Net Foreign: +Rp 50M | Top Buy: BNI, MNC | Top Sell: UBS, CGS"
      atau teks bebas yang mengandung keyword.

    Returns (score 0–100, signals list)
    """
    if not broker_text or len(broker_text.strip()) < 10:
        return 50, ["Tidak ada data broker summary"]

    text = broker_text.lower()
    signals = []
    score = 50

    # ── Net Foreign Flow ──
    import re as _re
    # Cari net foreign: "+Rp 50M", "-50 miliar", "net buy 100", dsb
    nf_match = _re.search(
        r'(?:net\s*foreign|asing\s*net|foreign\s*net)[^\d\-+]*([+\-]?[\d,.]+)\s*(m|jt|miliar|b|rb|ribu)?',
        text
    )
    if nf_match:
        val_str = nf_match.group(1).replace(',', '').replace('.', '')
        unit    = (nf_match.group(2) or '').lower()
        try:
            val = float(val_str)
            # Normalise ke miliar
            if unit in ('m', 'jt'):     val /= 1000
            elif unit in ('rb', 'ribu'): val /= 1_000_000
            if val > 0:
                score += min(20, val * 0.5)
                signals.append(f"✅ Net Foreign BUY Rp{val:.1f}M - asing akumulasi")
            elif val < 0:
                score -= min(20, abs(val) * 0.5)
                signals.append(f"🔴 Net Foreign SELL Rp{abs(val):.1f}M - asing distribusi")
        except:
            pass

    # ── Keyword detection: akumulasi vs distribusi ──
    AKUMULASI_KW = [
        "akumulasi", "accumulation", "net buy", "net beli",
        "foreign buy", "asing beli", "big buyer", "institutional buy",
        "bandar masuk", "smart money buy", "stealth buy"
    ]
    DISTRIBUSI_KW = [
        "distribusi", "distribution", "net sell", "net jual",
        "foreign sell", "asing jual", "big seller", "institutional sell",
        "bandar keluar", "offloading", "take profit besar"
    ]

    akum_hits = sum(1 for kw in AKUMULASI_KW if kw in text)
    dist_hits = sum(1 for kw in DISTRIBUSI_KW if kw in text)

    if akum_hits > dist_hits and akum_hits >= 2:
        score += 18
        signals.append(f"🟢 Broker summary: sinyal AKUMULASI ({akum_hits} indikator)")
    elif akum_hits > dist_hits and akum_hits == 1:
        score += 8
        signals.append("🟡 Broker summary: sedikit sinyal akumulasi")
    elif dist_hits > akum_hits and dist_hits >= 2:
        score -= 18
        signals.append(f"🔴 Broker summary: sinyal DISTRIBUSI ({dist_hits} indikator)")
    elif dist_hits > akum_hits and dist_hits == 1:
        score -= 8
        signals.append("⚠️ Broker summary: sedikit sinyal distribusi")

    # ── IDX Counter-intuitive Logic ──
    # Buyer broker banyak + seller sedikit → distribusi (smart money jual ke retail FOMO)
    buyer_heavy = any(kw in text for kw in [
        "banyak buyer", "buyer mendominasi", "buyer > seller",
        "lebih banyak buyer", "buyer broker banyak"
    ])
    seller_heavy = any(kw in text for kw in [
        "banyak seller", "seller mendominasi", "seller > buyer",
        "lebih banyak seller", "seller broker banyak"
    ])

    if buyer_heavy:
        # Counter-intuitive: banyak buyer broker = DISTRIBUSI di IDX
        score -= 12
        signals.append("⚠️ IDX Counter-intuitive: banyak buyer broker → potensi DISTRIBUSI")
    if seller_heavy:
        # Counter-intuitive: banyak seller broker = AKUMULASI di IDX
        score += 12
        signals.append("🟢 IDX Counter-intuitive: banyak seller broker → potensi AKUMULASI smart money")

    # ── Specific broker tiers (asing premium = smart money) ──
    FOREIGN_SMART = ["ubs", "cgs", "clsa", "macquarie", "jp morgan", "jpmorgan",
                     "deutsche", "dbs", "cimb", "nomura", "merrill", "morgan stanley"]
    LOCAL_RETAIL  = ["mnc", "bni", "ipot", "sinarmas", "trimegah", "henan", "phillip",
                     "phintraco", "panin", "maybank", "kgs", "samuel"]

    foreign_buy  = sum(1 for b in FOREIGN_SMART if b in text and
                       any(f"{b}" in seg and ("buy" in seg or "beli" in seg)
                           for seg in text.split(',')))
    foreign_sell = sum(1 for b in FOREIGN_SMART if b in text and
                       any(f"{b}" in seg and ("sell" in seg or "jual" in seg)
                           for seg in text.split(',')))

    if foreign_buy >= 2:
        score += 15
        signals.append(f"✅ {foreign_buy} broker asing premium di sisi BUY - institusi masuk")
    if foreign_sell >= 2:
        score -= 12
        signals.append(f"🔴 {foreign_sell} broker asing premium di sisi SELL - smart money keluar")

    return _clamp(score), signals


# ─────────────────────────────────────────────
# MAIN SCORING ENGINE
# ─────────────────────────────────────────────
def sigma_score(
    ticker: str,
    price_data: PriceData,
    fundamental_data: Optional[FundamentalData] = None,
    broker_summary: Optional[str] = None,
) -> SigmaScoreResult:
    """
    Hitung SIGMA Score untuk satu saham.

    Parameters:
        ticker          : kode saham IDX (4 huruf)
        price_data      : PriceData dengan OHLCV minimal 20 hari
        fundamental_data: FundamentalData (opsional)
        broker_summary  : teks broker summary dari user (opsional, meningkatkan akurasi bandar score)

    Returns:
        SigmaScoreResult
    """
    # ── Hitung semua komponen ──
    t_score, t_signals = _score_teknikal(price_data)
    v_score, v_signals = _score_volume(price_data)

    # Bandar score: blend volume-based + broker summary jika ada
    b_score_vol, b_signals_vol = _score_bandar(price_data)
    if broker_summary:
        b_score_broker, b_signals_broker = score_bandar_from_broker_summary(broker_summary)
        # Jika broker summary tersedia → bobot 60% broker, 40% volume behavior
        b_score   = int(b_score_broker * 0.60 + b_score_vol * 0.40)
        b_signals = b_signals_broker + b_signals_vol
    else:
        b_score   = b_score_vol
        b_signals = b_signals_vol

    f_score, f_signals = _score_fundamental(fundamental_data)
    m_score, m_signals = _score_momentum_rs(price_data)

    # ── Weighted Final Score ──
    raw = (
        t_score * WEIGHTS["teknikal"]    +
        v_score * WEIGHTS["volume"]      +
        b_score * WEIGHTS["bandar"]      +
        f_score * WEIGHTS["fundamental"] +
        m_score * WEIGHTS["momentum_rs"]
    )
    final_score = _clamp(raw)

    # ── Grade ──
    grade = "DANGER"
    badge_color = "#ff1744"
    for threshold, g, color in GRADE_THRESHOLDS:
        if final_score >= threshold:
            grade = g
            badge_color = color
            break

    # ── Confidence Level ──
    data_len = len(price_data.closes)
    has_fundamental = fundamental_data is not None and any([
        fundamental_data.roe, fundamental_data.der,
        fundamental_data.pbv, fundamental_data.eps_growth
    ])
    has_ihsg = len(price_data.ihsg_closes) >= 20

    conf_points = 0
    if data_len >= 60:  conf_points += 2
    elif data_len >= 20: conf_points += 1
    if has_fundamental:  conf_points += 1
    if has_ihsg:         conf_points += 1
    if broker_summary:   conf_points += 1  # broker data meningkatkan confidence

    confidence = "HIGH" if conf_points >= 3 else ("MEDIUM" if conf_points >= 2 else "LOW")

    # ── Trade Levels ──
    levels = _calc_trade_levels(price_data)

    # ── Aggregate Top Signals (max 6, prioritaskan yang relevan) ──
    all_signals = t_signals + v_signals + b_signals + f_signals + m_signals
    # Prioritaskan sinyal dengan emoji ✅🟢 (bullish) dan 🔴 (bearish), batasi 6
    top_signals = [s for s in all_signals if any(e in s for e in ["✅","🟢","🌟","⚡"])][:3]
    top_signals += [s for s in all_signals if any(e in s for e in ["🔴","💀","⛔"])][:2]
    top_signals += [s for s in all_signals if any(e in s for e in ["⚠️","🟡"])][:1]

    breakdown = {
        "teknikal":    t_score,
        "volume":      v_score,
        "bandar":      b_score,
        "fundamental": f_score,
        "momentum_rs": m_score,
    }

    return SigmaScoreResult(
        score       = final_score,
        grade       = grade,
        badge_color = badge_color,
        breakdown   = breakdown,
        signals     = top_signals if top_signals else all_signals[:4],
        confidence  = confidence,
        entry_zone  = levels.get("entry_zone"),
        sl_zone     = levels.get("sl"),
        tp1         = levels.get("tp1"),
        tp2         = levels.get("tp2"),
        tp3         = levels.get("tp3"),
        rr_ratio    = levels.get("rr_ratio"),
    )


# ─────────────────────────────────────────────
# BATCH SCORER - untuk Alpha Screener
# ─────────────────────────────────────────────
def batch_sigma_score(ticker_price_dict: dict, ihsg_closes: list = None) -> dict:
    """
    Score banyak saham sekaligus dari data yang sudah di-fetch.

    ticker_price_dict format (dari _reco_fetch_prices):
    {
        "BBCA": {
            "closes": [...], "volumes": [...], "highs": [...], "lows": [...],
            "fundamental": FundamentalData (opsional)
        }
    }

    Returns: { "BBCA": SigmaScoreResult, ... } - sorted by score descending
    """
    results = {}
    ihsg = ihsg_closes or []

    for ticker, data in ticker_price_dict.items():
        try:
            pd_obj = PriceData(
                closes        = data.get("closes", []),
                volumes       = data.get("volumes", []),
                highs         = data.get("highs", []),
                lows          = data.get("lows", []),
                ihsg_closes   = ihsg,
            )
            fd_obj = data.get("fundamental", None)
            results[ticker] = sigma_score(ticker, pd_obj, fd_obj)
        except Exception as e:
            # Jangan crash batch karena satu saham gagal
            results[ticker] = SigmaScoreResult(
                score=0, grade="N/A", badge_color="#555555",
                breakdown={}, signals=[f"Error: {str(e)[:60]}"],
                confidence="LOW"
            )

    # Sort by score descending
    return dict(sorted(results.items(), key=lambda x: x[1].score, reverse=True))


# ─────────────────────────────────────────────
# STREAMLIT RENDERER - Badge & Breakdown Card
# ─────────────────────────────────────────────
def render_sigma_score_badge(result: SigmaScoreResult, ticker: str = "", compact: bool = False) -> str:
    """
    Return HTML string untuk badge SIGMA Score.
    compact=True → hanya angka + grade (untuk tabel/card kecil)
    compact=False → full breakdown dengan progress bars
    """
    c = result.badge_color
    score = result.score
    grade = result.grade

    if compact:
        return f"""
<div style="display:inline-flex;align-items:center;gap:8px;background:rgba(0,0,0,0.25);
border:1px solid {c}44;border-radius:8px;padding:6px 12px;">
  <span style="font-family:'IBM Plex Mono',monospace;font-size:1.25rem;font-weight:700;color:{c};">{score}</span>
  <div>
    <div style="font-family:'IBM Plex Mono',monospace;font-size:0.72rem;color:{c};font-weight:600;letter-spacing:0.1em;">{grade}</div>
    <div style="font-family:'IBM Plex Mono',monospace;font-size:0.72rem;color:#888;letter-spacing:0.05em;">SIGMA SCORE</div>
  </div>
</div>"""

    # Full card
    bars = ""
    labels = {"teknikal":"Teknikal","volume":"Volume","bandar":"Bandar","fundamental":"Fundamental","momentum_rs":"RS Momentum"}
    bar_colors = {"teknikal":"#009dff","volume":"#a78bfa","bandar":"#ff6d00","fundamental":"#69f0ae","momentum_rs":"#ffd740"}

    for key, label in labels.items():
        val = result.breakdown.get(key, 50)
        bc  = bar_colors.get(key, "#888")
        wt  = int(WEIGHTS.get(key, 0.2) * 100)
        bars += f"""
<div style="margin-bottom:6px;">
  <div style="display:flex;justify-content:space-between;font-family:'IBM Plex Mono',monospace;font-size:0.72rem;color:#aaa;margin-bottom:2px;">
    <span>{label} <span style="color:#666;">({wt}%)</span></span>
    <span style="color:{bc};font-weight:600;">{val}</span>
  </div>
  <div style="background:rgba(255,255,255,0.07);border-radius:3px;height:4px;overflow:hidden;">
    <div style="width:{val}%;height:100%;background:{bc};border-radius:3px;transition:width 0.4s;"></div>
  </div>
</div>"""

    signals_html = "".join(f"<div style='font-size:0.72rem;color:#ccc;margin-bottom:3px;'>{s}</div>" for s in result.signals[:5])

    conf_color = {"HIGH":"#69f0ae","MEDIUM":"#ffd740","LOW":"#ff6d00"}.get(result.confidence, "#888")
    ticker_display = f" - {ticker}" if ticker else ""

    # Entry/SL/TP summary
    levels_html = ""
    if result.entry_zone:
        lo, hi = result.entry_zone
        levels_html += f"<div style='font-size:0.72rem;margin-top:8px;border-top:1px solid rgba(255,255,255,0.07);padding-top:8px;'>"
        levels_html += f"<span style='color:#ffd740;font-family:IBM Plex Mono,monospace;'>🎯 Entry</span> <span style='color:#eee;'>Rp{lo:,.0f} – Rp{hi:,.0f}</span> &nbsp;"
        if result.sl_zone:
            levels_html += f"<span style='color:#ff5555;font-family:IBM Plex Mono,monospace;'>🛑 SL</span> <span style='color:#eee;'>Rp{result.sl_zone:,.0f}</span> &nbsp;"
        if result.tp1:
            levels_html += f"<span style='color:#69f0ae;font-family:IBM Plex Mono,monospace;'>✅ TP1</span> <span style='color:#eee;'>Rp{result.tp1:,.0f}</span>"
        if result.rr_ratio:
            levels_html += f" &nbsp;<span style='color:#a78bfa;font-family:IBM Plex Mono,monospace;'>R/R {result.rr_ratio:.1f}x</span>"
        levels_html += "</div>"

    return f"""
<div style="background:rgba(20,23,35,0.85);border:1px solid {c}55;border-left:4px solid {c};
border-radius:0 10px 10px 0;padding:16px 18px;margin:8px 0;box-sizing:border-box;">
  <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;">
    <div style="display:flex;align-items:center;gap:12px;">
      <div style="font-family:'IBM Plex Mono',monospace;font-size:2.2rem;font-weight:700;color:{c};line-height:1;">{score}</div>
      <div>
        <div style="font-family:'IBM Plex Mono',monospace;font-size:0.8rem;color:{c};font-weight:700;letter-spacing:0.12em;">{grade}</div>
        <div style="font-family:'IBM Plex Mono',monospace;font-size:0.72rem;color:#666;letter-spacing:0.08em;">SIGMA SCORE{ticker_display}</div>
      </div>
    </div>
    <div style="text-align:right;">
      <div style="font-family:'IBM Plex Mono',monospace;font-size:0.72rem;color:{conf_color};letter-spacing:0.1em;">CONFIDENCE: {result.confidence}</div>
    </div>
  </div>
  {bars}
  <div style="margin-top:10px;border-top:1px solid rgba(255,255,255,0.07);padding-top:8px;">
    {signals_html}
  </div>
  {levels_html}
</div>"""


# ─────────────────────────────────────────────
# HELPER: build PriceData from yfinance history df
# ─────────────────────────────────────────────
def price_data_from_yf(history_df, ihsg_df=None) -> PriceData:
    """
    Konversi yfinance history DataFrame → PriceData.
    history_df = yf.Ticker('BBCA.JK').history(period='3mo')
    """
    return PriceData(
        closes  = history_df["Close"].tolist(),
        volumes = history_df["Volume"].tolist(),
        highs   = history_df["High"].tolist(),
        lows    = history_df["Low"].tolist(),
        ihsg_closes = ihsg_df["Close"].tolist() if ihsg_df is not None and not ihsg_df.empty else [],
    )


def fundamental_data_from_dict(d: dict) -> FundamentalData:
    """
    Konversi output _fetch_multi_fundamental() → FundamentalData.
    """
    def _pct(val):
        """Handle both decimal (0.15) and percent (15.0) format."""
        if val is None: return None
        return val if val > 5 else val * 100  # balikin dalam persen

    roe = d.get("roe")
    roe_pct = _pct(roe) if roe is not None else None

    eps_now  = d.get("eps")
    eps_prev = d.get("eps_last_year")
    eps_growth = None
    if eps_now and eps_prev and eps_prev != 0:
        eps_growth = (eps_now-eps_prev) / abs(eps_prev) * 100

    return FundamentalData(
        roe           = roe_pct,
        der           = d.get("der"),
        pbv           = d.get("pbv"),
        eps_growth    = eps_growth,
        net_margin    = _pct(d.get("net_margin")),
        current_ratio = d.get("current_ratio"),
    )

# Alias agar pemanggilan di app tetap konsisten
_sigma_score_calc = sigma_score

# ═══════════════════════════════════════════════════════════════════════════════
# MnM ZONE DETECTION ENGINE v2.0 — Embedded dari zone_engine_core.py
# IFVG / FVG / Order Block / Supply & Demand / Volume Intelligence
# Multi-Timeframe: Daily | Weekly | 4H
# ═══════════════════════════════════════════════════════════════════════════════
from dataclasses import dataclass, field as dc_field
from typing import List, Optional
import math


# ─────────────────────────────────────────────
# DATACLASS
# ─────────────────────────────────────────────
@dataclass
class ZoneResult:
    ticker: str = ""
    ifvg_bull: list = dc_field(default_factory=list)
    ifvg_bear: list = dc_field(default_factory=list)
    fvg_bull:  list = dc_field(default_factory=list)
    fvg_bear:  list = dc_field(default_factory=list)
    ob_bull:   list = dc_field(default_factory=list)
    ob_bear:   list = dc_field(default_factory=list)
    supply:    list = dc_field(default_factory=list)
    demand:    list = dc_field(default_factory=list)
    vol_score:       int  = 50
    vol_type:        str  = "-"
    vol_freq_signal: str  = "-"
    accum_score:     int  = 50
    breakout_valid:  bool = False
    false_breakout:  bool = False
    confluence_score: int = 0
    confluence_zones: list = dc_field(default_factory=list)
    nearest_zone:    str  = "-"
    nearest_zone_type: str = "-"
    tf_summary: dict = dc_field(default_factory=dict)
    zone_signals: list = dc_field(default_factory=list)


# ─────────────────────────────────────────────
# HELPERS
# ─────────────────────────────────────────────
def _calc_atr_z(highs, lows, closes, period=14):
    if len(closes) < period + 1:
        return (max(highs[-5:]) - min(lows[-5:])) / 2 if highs else 1
    trs = []
    for i in range(1, min(period + 1, len(closes))):
        tr = max(
            highs[-i] - lows[-i],
            abs(highs[-i] - closes[-i-1]),
            abs(lows[-i] - closes[-i-1]),
        )
        trs.append(tr)
    return sum(trs) / len(trs) if trs else 1


# ─────────────────────────────────────────────
# FVG + IFVG DETECTION
# ─────────────────────────────────────────────
def _detect_fvg(closes, highs, lows, atr_val):
    """
    Bull FVG  : low[i] > high[i-2]
    Bear FVG  : high[i] < low[i-2]
    Bull IFVG : low[i] > high[i-2] AND close[i-1] > high[i-2]
    Bear IFVG : high[i] < low[i-2] AND close[i-1] < low[i-2]
    Filter   : gap > 0.1 * ATR
    """
    n = len(closes)
    if n < 3:
        return [], [], [], []

    fvg_bull, fvg_bear, ifvg_bull, ifvg_bear = [], [], [], []
    current_price = closes[-1]
    start_fvg  = max(2, n - 100)
    start_ifvg = max(2, n - 50)

    for i in range(start_fvg, n):
        h2 = highs[i-2]; l2 = lows[i-2]
        h1 = highs[i-1]; c1 = closes[i-1]
        hi = highs[i];   li = lows[i]

        gap_bull = li - h2  if li > h2 else 0
        gap_bear = l2 - hi  if l2 > hi else 0
        min_size = atr_val * 0.1

        if gap_bull > min_size:
            z = {"top": li, "bot": h2, "mid": (li+h2)/2, "idx": i, "size": gap_bull}
            if current_price >= h2:           # tidak mitigasi
                fvg_bull.append(z)
            if i >= start_ifvg and c1 > h2:   # IFVG
                z2 = dict(z); z2["inverted"] = False
                if current_price >= h2:
                    ifvg_bull.append(z2)

        if gap_bear > min_size:
            z = {"top": l2, "bot": hi, "mid": (l2+hi)/2, "idx": i, "size": gap_bear}
            if current_price <= l2:
                fvg_bear.append(z)
            if i >= start_ifvg and c1 < l2:
                z2 = dict(z); z2["inverted"] = False
                if current_price <= l2:
                    ifvg_bear.append(z2)

    return fvg_bull[-3:], fvg_bear[-3:], ifvg_bull[-3:], ifvg_bear[-3:]


# ─────────────────────────────────────────────
# ORDER BLOCK DETECTION
# ─────────────────────────────────────────────
def _detect_order_blocks(closes, highs, lows, swing_len=10):
    n = len(closes)
    if n < swing_len * 2 + 2:
        return [], []

    current_price = closes[-1]
    start = max(0, n - 200)
    sc = closes[start:]; sh = highs[start:]; sl = lows[start:]
    nn = len(sc)

    def swing_highs(h, w):
        return [(i, h[i]) for i in range(w, len(h)-w)
                if h[i] == max(h[max(0,i-w):i+w+1])]

    def swing_lows(l, w):
        return [(i, l[i]) for i in range(w, len(l)-w)
                if l[i] == min(l[max(0,i-w):i+w+1])]

    bull_obs, bear_obs = [], []

    for sh_idx, sh_val in swing_highs(sh, swing_len):
        break_idx = next((j for j in range(sh_idx+1, nn) if sc[j] > sh_val), None)
        if break_idx is None: continue
        for k in range(sh_idx, max(0, sh_idx-swing_len), -1):
            if k < 1: break
            if sc[k] < sc[k-1]:   # candle merah (proxy)
                ob_top = max(sc[k], sc[k-1])
                ob_bot = sl[k]
                breaker = current_price < ob_bot
                bull_obs.append({"top": ob_top, "bot": ob_bot, "mid": (ob_top+ob_bot)/2,
                                  "breaker": breaker})
                break

    for sl_idx, sl_val in swing_lows(sl, swing_len):
        break_idx = next((j for j in range(sl_idx+1, nn) if sc[j] < sl_val), None)
        if break_idx is None: continue
        for k in range(sl_idx, max(0, sl_idx-swing_len), -1):
            if k < 1: break
            if sc[k] > sc[k-1]:   # candle hijau (proxy)
                ob_top = sh[k]
                ob_bot = min(sc[k], sc[k-1])
                breaker = current_price > ob_top
                bear_obs.append({"top": ob_top, "bot": ob_bot, "mid": (ob_top+ob_bot)/2,
                                  "breaker": breaker})
                break

    tol = 0.15
    def rel(z, p): return abs(p - z["mid"]) / (z["mid"]+1) < tol
    bull_rel = sorted([z for z in bull_obs if rel(z, current_price) or current_price > z["bot"]],
                      key=lambda z: abs(current_price - z["mid"]))
    bear_rel = sorted([z for z in bear_obs if rel(z, current_price) or current_price < z["top"]],
                      key=lambda z: abs(current_price - z["mid"]))
    return bull_rel[:3], bear_rel[:3]


# ─────────────────────────────────────────────
# SUPPLY / DEMAND DETECTION
# ─────────────────────────────────────────────
def _detect_supply_demand(closes, highs, lows, volumes, atr_val):
    n = len(closes)
    if n < 10:
        return [], []

    current_price = closes[-1]
    avg_vol = sum(volumes[-20:]) / min(20, len(volumes))
    supply_zones, demand_zones = [], []
    start = max(6, n - 100)

    def is_bull(k): return closes[k] > closes[k-1] if k > 0 else False
    def is_bear(k): return closes[k] < closes[k-1] if k > 0 else False

    for i in range(start, n - 1):
        vol_i = volumes[i] if i < len(volumes) else avg_vol

        # Supply
        if i >= 2 and is_bear(i) and is_bear(i-1) and is_bear(i-2) and vol_i > avg_vol:
            for j in range(i-3, max(0, i-8), -1):
                if is_bull(j):
                    top = highs[j] + atr_val * 2
                    bot = lows[j]
                    if current_price < top:
                        supply_zones.append({"top": top, "bot": bot, "mid": (top+bot)/2, "idx": j})
                    break

        # Demand
        if i >= 2 and is_bull(i) and is_bull(i-1) and is_bull(i-2) and vol_i > avg_vol:
            for j in range(i-3, max(0, i-8), -1):
                if is_bear(j):
                    top = highs[j]
                    bot = lows[j] - atr_val * 2
                    if current_price > bot:
                        demand_zones.append({"top": top, "bot": bot, "mid": (top+bot)/2, "idx": j})
                    break

    def dedup(zones, pct=0.02):
        res = []
        for z in zones:
            if not any(abs(z["mid"]-r["mid"]) / (r["mid"]+1) < pct for r in res):
                res.append(z)
        return res

    supply_zones = dedup(supply_zones[-5:])
    demand_zones = dedup(demand_zones[-5:])

    sup_above = sorted([z for z in supply_zones if z["bot"] > current_price], key=lambda z: z["bot"])
    dem_below = sorted([z for z in demand_zones if z["top"] < current_price], key=lambda z: -z["top"])
    return sup_above[:3], dem_below[:3]


# ─────────────────────────────────────────────
# VOLUME INTELLIGENCE
# ─────────────────────────────────────────────
def _vol_intelligence(closes, highs, lows, volumes):
    """
    IDX-specific volume scoring:
    - Volume besar + frekuensi kecil (proxy: candle body ratio) = Akumulasi
    - Volume besar + frekuensi besar = Distribusi / Noise
    - Breakout + block trade = True Breakout
    - Breakout + retail = False Breakout
    """
    n = len(closes)
    if n < 5:
        return 50, "-", "-", 50, False, False

    avg20 = sum(volumes[-20:]) / min(20, len(volumes))
    avg5  = sum(volumes[-5:])  / min(5, len(volumes))
    vol_now = volumes[-1]
    spike_ratio = vol_now / (avg20 + 1)

    # Proxy frekuensi dari candle anatomy
    body_ratios = []
    for i in range(1, min(6, n)):
        rng  = highs[-i] - lows[-i]
        body = abs(closes[-i] - closes[-i-1]) if i+1 < n else rng*0.5
        body_ratios.append(body / (rng + 0.001))
    avg_br = sum(body_ratios) / len(body_ratios) if body_ratios else 0.5

    is_block  = avg_br > 0.60   # sedikit transaksi besar
    is_retail = avg_br < 0.35   # banyak transaksi kecil

    # Posisi harga dalam range 20 hari
    h20 = max(highs[-20:]) if len(highs) >= 20 else highs[-1]
    l20 = min(lows[-20:])  if len(lows)  >= 20 else lows[-1]
    pct = (closes[-1] - l20) / (h20 - l20 + 0.001)
    at_top = pct > 0.75
    at_bot = pct < 0.25

    # Breakout check
    is_bo  = len(highs) >= 21 and closes[-1] > max(highs[-21:-1])
    is_bdo = len(lows)  >= 21 and closes[-1] < min(lows[-21:-1])

    vs, ac = 50, 50
    vt = "Normal"
    vf = "Mixed"
    bv = False
    fbv = False

    if spike_ratio >= 1.5 and is_block and at_bot:
        vs = min(90, 55 + spike_ratio * 8)
        ac = min(92, 60 + spike_ratio * 7)
        vt = "Block Trade Akumulasi ✅"
        vf = "Smart Money"

    elif avg5 < avg20 * 0.5 and at_bot:
        vs = 72; ac = 75
        vt = "Akumulasi Stealth 🔵"
        vf = "Smart Money"

    elif spike_ratio >= 2.0 and at_top:
        vs = max(20, 55 - spike_ratio * 6)
        ac = max(15, 50 - spike_ratio * 7)
        vt = "Distribusi Block Trade 🔴" if is_block else "Distribusi Ritel FOMO 🔴"
        vf = "Smart Money Jual" if is_block else "Ritel Noise"

    elif is_bo and spike_ratio >= 2.0 and is_block:
        vs = min(88, 65 + spike_ratio * 5)
        ac = min(85, 60 + spike_ratio * 5)
        vt = "True Breakout ⚡"
        vf = "Smart Money"
        bv = True

    elif is_bo and spike_ratio >= 2.0 and is_retail:
        vs = 35; ac = 30
        vt = "False Breakout ⚠️"
        vf = "Ritel Noise"
        fbv = True

    elif is_retail:
        vs = 45; vt = "Volume Ritel (Noise)"; vf = "Ritel"

    elif spike_ratio >= 3.0:
        ret5 = (closes[-1]-closes[-6])/(closes[-6]+1)*100 if n>=6 else 0
        vs = 60 if ret5 > 1 else 42
        vt = f"Vol Spike {spike_ratio:.1f}x 🟡"
        vf = "Block Trade" if is_block else "Mixed"

    elif avg5 < avg20 * 0.4:
        vs = 65; ac = 68
        vt = "Dry-Up (Siaga Breakout) 🔵"
        vf = "Neutral"

    # Price-Vol divergence penalty
    if n >= 6:
        pchg = (closes[-1]-closes[-6])/(closes[-6]+1)*100
        v5old = sum(volumes[-11:-6])/5 if len(volumes)>=11 else avg20
        vchg  = (avg5-v5old)/(v5old+1)*100
        if pchg > 2 and vchg < -20:
            vs = max(25, vs - 15)
            vt += " | Divergensi ⚠️"

    return (min(100, max(0, int(vs))), vt, vf,
            min(100, max(0, int(ac))), bv, fbv)


# ─────────────────────────────────────────────
# CONFLUENCE SCORING
# ─────────────────────────────────────────────
def _confluence_at_price(price, ifvg_bull, ifvg_bear, fvg_bull, fvg_bear,
                          ob_bull, ob_bear, supply, demand, pct_tol=0.02):
    w = {"IFVG": 3, "FVG": 2, "OB": 2, "S/D": 1}

    def in_zone(z, p, tol):
        return z["bot"]*(1-tol) <= p <= z["top"]*(1+tol)

    conf_zones = []
    for z in ifvg_bull:
        if in_zone(z, price, pct_tol): conf_zones.append(("IFVG Bull", z["mid"]))
    for z in ifvg_bear:
        if in_zone(z, price, pct_tol): conf_zones.append(("IFVG Bear", z["mid"]))
    for z in fvg_bull:
        if in_zone(z, price, pct_tol): conf_zones.append(("FVG Bull", z["mid"]))
    for z in fvg_bear:
        if in_zone(z, price, pct_tol): conf_zones.append(("FVG Bear", z["mid"]))
    for z in ob_bull:
        if in_zone(z, price, pct_tol): conf_zones.append(("OB Bull", z["mid"]))
    for z in ob_bear:
        if in_zone(z, price, pct_tol): conf_zones.append(("OB Bear", z["mid"]))
    for z in supply:
        if in_zone(z, price, pct_tol): conf_zones.append(("Supply", z["mid"]))
    for z in demand:
        if in_zone(z, price, pct_tol): conf_zones.append(("Demand", z["mid"]))

    raw = 0
    for name, _ in conf_zones:
        for k, wv in w.items():
            if k in name: raw += wv; break
        else: raw += 1

    all_zones = (
        [("IFVG Bull", z["mid"], "support")   for z in ifvg_bull] +
        [("IFVG Bear", z["mid"], "resistance") for z in ifvg_bear] +
        [("FVG Bull",  z["mid"], "support")   for z in fvg_bull]  +
        [("FVG Bear",  z["mid"], "resistance") for z in fvg_bear]  +
        [("OB Bull",   z["mid"], "support")   for z in ob_bull]   +
        [("OB Bear",   z["mid"], "resistance") for z in ob_bear]   +
        [("Demand",    z["mid"], "support")   for z in demand]    +
        [("Supply",    z["mid"], "resistance") for z in supply]
    )
    nearest = min(all_zones, key=lambda x: abs(x[1]-price), default=None)
    nname = nearest[0] if nearest else "-"
    ntype = nearest[2] if nearest else "-"

    return min(10, raw), [z[0] for z in conf_zones], nname, ntype


# ─────────────────────────────────────────────
# SINGLE TF DETECTION
# ─────────────────────────────────────────────
def detect_zones_single_tf(closes, highs, lows, volumes, tf_label="D", ticker="") -> ZoneResult:
    result = ZoneResult(ticker=ticker)
    n = len(closes)
    if n < 10:
        return result

    price = closes[-1]
    atr   = _calc_atr_z(highs, lows, closes, 14)

    fb, fb2, ifb, ifb2 = _detect_fvg(closes, highs, lows, atr)
    ob_b, ob_be = _detect_order_blocks(closes, highs, lows)
    sup_z, dem_z = _detect_supply_demand(closes, highs, lows, volumes, atr)
    vs, vt, vf, ac, bv, fbv = _vol_intelligence(closes, highs, lows, volumes)
    cs, cz, nz, nzt = _confluence_at_price(price, ifb, ifb2, fb, fb2, ob_b, ob_be, sup_z, dem_z)

    result.ifvg_bull        = [dict(z, tf=tf_label) for z in ifb]
    result.ifvg_bear        = [dict(z, tf=tf_label) for z in ifb2]
    result.fvg_bull         = [dict(z, tf=tf_label) for z in fb]
    result.fvg_bear         = [dict(z, tf=tf_label) for z in fb2]
    result.ob_bull          = [dict(z, tf=tf_label) for z in ob_b]
    result.ob_bear          = [dict(z, tf=tf_label) for z in ob_be]
    result.supply           = [dict(z, tf=tf_label) for z in sup_z]
    result.demand           = [dict(z, tf=tf_label) for z in dem_z]
    result.vol_score        = vs
    result.vol_type         = vt
    result.vol_freq_signal  = vf
    result.accum_score      = ac
    result.breakout_valid   = bv
    result.false_breakout   = fbv
    result.confluence_score = cs
    result.confluence_zones = cz
    result.nearest_zone     = nz
    result.nearest_zone_type = nzt

    sigs = []
    if ifb:    sigs.append(f"✅ IFVG Bull {tf_label}: Rp{ifb[-1]['top']:,.0f}–{ifb[-1]['bot']:,.0f}")
    if ifb2:   sigs.append(f"🔴 IFVG Bear {tf_label}: Rp{ifb2[-1]['top']:,.0f}–{ifb2[-1]['bot']:,.0f}")
    if fb:     sigs.append(f"🔵 FVG Bull {tf_label}: Rp{fb[-1]['top']:,.0f}–{fb[-1]['bot']:,.0f}")
    if dem_z:  sigs.append(f"🟢 Demand {tf_label}: Rp{dem_z[0]['top']:,.0f}–{dem_z[0]['bot']:,.0f}")
    if sup_z:  sigs.append(f"⚠️ Supply {tf_label}: Rp{sup_z[0]['top']:,.0f}–{sup_z[0]['bot']:,.0f}")
    if cs >= 3: sigs.append(f"⚡ CONFLUENCE {cs}/10 di {tf_label}: {', '.join(cz[:3])}")
    if bv:     sigs.append(f"🚀 TRUE BREAKOUT {tf_label} terkonfirmasi")
    if fbv:    sigs.append(f"⛔ FALSE BREAKOUT {tf_label} terdeteksi")
    result.zone_signals = sigs

    return result


# ─────────────────────────────────────────────
# MULTI-TF DETECTION (with yfinance)
# ─────────────────────────────────────────────
def detect_zones_multi_tf(ticker: str) -> ZoneResult:
    """
    Deteksi zona multi-timeframe.
    TF: Daily (200c), Weekly (52c), 4H (120c)
    """
    try:
        import yfinance as yf
    except ImportError:
        return ZoneResult(ticker=ticker)

    master = ZoneResult(ticker=ticker)
    tf_map = {
        "D":  ("6mo",  "1d"),
        "W":  ("2y",   "1wk"),
        "4H": ("60d",  "4h"),
    }

    all_signals = []
    combined_conf = 0

    for tf_label, (period, interval) in tf_map.items():
        try:
            hist = yf.Ticker(f"{ticker}.JK").history(
                period=period, interval=interval, auto_adjust=True
            )
            if hist.empty or len(hist) < 10:
                continue

            c = hist["Close"].tolist()
            h = hist["High"].tolist()
            l = hist["Low"].tolist()
            v = hist["Volume"].tolist()

            tf_res = detect_zones_single_tf(c, h, l, v, tf_label, ticker)

            master.tf_summary[tf_label] = {
                "ifvg_bull":  tf_res.ifvg_bull,
                "ifvg_bear":  tf_res.ifvg_bear,
                "fvg_bull":   tf_res.fvg_bull,
                "fvg_bear":   tf_res.fvg_bear,
                "ob_bull":    tf_res.ob_bull,
                "ob_bear":    tf_res.ob_bear,
                "supply":     tf_res.supply,
                "demand":     tf_res.demand,
                "vol_score":  tf_res.vol_score,
                "vol_type":   tf_res.vol_type,
                "conf_score": tf_res.confluence_score,
                "conf_zones": tf_res.confluence_zones,
                "nearest_zone": tf_res.nearest_zone,
                "nearest_zone_type": tf_res.nearest_zone_type,
            }

            if tf_label == "D":
                master.ifvg_bull        = tf_res.ifvg_bull
                master.ifvg_bear        = tf_res.ifvg_bear
                master.fvg_bull         = tf_res.fvg_bull
                master.fvg_bear         = tf_res.fvg_bear
                master.ob_bull          = tf_res.ob_bull
                master.ob_bear          = tf_res.ob_bear
                master.supply           = tf_res.supply
                master.demand           = tf_res.demand
                master.vol_score        = tf_res.vol_score
                master.vol_type         = tf_res.vol_type
                master.vol_freq_signal  = tf_res.vol_freq_signal
                master.accum_score      = tf_res.accum_score
                master.breakout_valid   = tf_res.breakout_valid
                master.false_breakout   = tf_res.false_breakout
                master.nearest_zone     = tf_res.nearest_zone
                master.nearest_zone_type = tf_res.nearest_zone_type

            all_signals.extend(tf_res.zone_signals)
            combined_conf += tf_res.confluence_score

        except Exception:
            continue

    master.confluence_score = min(10, combined_conf // max(1, len(tf_map)))
    master.zone_signals     = all_signals[:8]
    return master


# ─────────────────────────────────────────────
# ZONE BADGE HTML (untuk kolom tabel screener)
# ─────────────────────────────────────────────
def zone_badge_html(result: ZoneResult, price: float = 0, C: dict = None) -> str:
    if C is None: C = {}
    parts = []

    if result.ifvg_bull: parts.append('<span title="IFVG Bull" style="color:#4285F4;font-weight:700;font-size:11px;">IFVG</span>')
    if result.ifvg_bear: parts.append('<span title="IFVG Bear" style="color:#aaa;font-weight:700;font-size:11px;">IFVG▼</span>')
    if result.fvg_bull:  parts.append('<span title="FVG Bull" style="color:#0ea5e9;font-size:11px;">FVG</span>')
    if result.ob_bull:   parts.append('<span title="OB Bull" style="color:#22c55e;font-size:11px;">OB</span>')
    if result.demand:    parts.append('<span title="Demand Zone" style="color:#009fd4;font-size:11px;">DMD</span>')
    if result.supply:    parts.append('<span title="Supply Zone" style="color:#888;font-size:11px;">SPY</span>')

    cs = result.confluence_score
    cc = "#00c853" if cs >= 5 else ("#ffd740" if cs >= 3 else "#888")
    if cs > 0:
        parts.append(
            f'<span style="background:{cc}22;color:{cc};border:1px solid {cc}55;'
            f'border-radius:3px;padding:1px 4px;font-size:10px;font-weight:700;font-family:\'IBM Plex Mono\',monospace;">'
            f'C:{cs}</span>'
        )

    vt = result.vol_type or "-"
    if "Akumulasi" in vt or "True Breakout" in vt:
        vc, vbg = "#00e5a0", "rgba(0,229,160,0.1)"
    elif "Distribusi" in vt or "False" in vt:
        vc, vbg = "#f23645", "rgba(242,54,69,0.1)"
    elif "Dry-Up" in vt:
        vc, vbg = "#4285F4", "rgba(66,133,244,0.1)"
    else:
        vc, vbg = "#888", "transparent"

    vol_short = vt.split(" ")[0][:8]
    parts.append(
        f'<span style="background:{vbg};color:{vc};border:1px solid {vc}33;'
        f'border-radius:3px;padding:1px 4px;font-size:10px;font-family:\'IBM Plex Mono\',monospace;">'
        f'{vol_short}</span>'
    )

    if result.nearest_zone != "-":
        nz = result.nearest_zone
        nc = "#009fd4" if ("Bull" in nz or "Demand" in nz) else "#f23645"
        parts.append(f'<span style="color:{nc};font-size:10px;">→{nz[:8]}</span>')

    return " ".join(parts) if parts else '<span style="color:#555;font-size:10px;">-</span>'


# ─────────────────────────────────────────────
# ZONE DETAIL CARD HTML (untuk section detail)
# ─────────────────────────────────────────────
def zone_detail_html(result: ZoneResult, price: float = 0, C: dict = None) -> str:
    """
    Hanya render Volume Intelligence + Akumulasi Score.
    Tabel zona (IFVG/FVG/OB/S&D) TIDAK ditampilkan ke user — hanya digunakan sistem untuk AI context.
    """
    if C is None: C = {}
    met_bg     = C.get("bg", "#050a15")
    met_border = C.get("border", "#1a2f50")
    text_main  = C.get("text", "#e2e8f0")
    text_sub   = C.get("text_muted", "#64748b")

    cs = result.confluence_score
    cc = "#00c853" if cs >= 5 else ("#ffd740" if cs >= 3 else "#888")

    vs = result.vol_score
    if vs >= 60:   vc, vbg = "#00e5a0", "rgba(0,229,160,0.08)"
    elif vs >= 45: vc, vbg = "#ffd740", "rgba(255,215,64,0.07)"
    else:          vc, vbg = "#f23645", "rgba(242,54,69,0.08)"

    # ── Pre-build zone signals HTML (avoid nested f-string leak) ──
    _zone_sigs_html = (
        f'<div style="border-top:1px solid {met_border};padding-top:8px;margin-top:10px;">'
        + "".join(f'<div style="font-size:0.72rem;color:{text_sub};margin-bottom:3px;">{s}</div>' for s in result.zone_signals[:4])
        + '</div>'
    ) if result.zone_signals else ''

    html = f"""
<div style="background:{met_bg};border:1px solid {met_border};border-radius:8px;padding:14px;margin:8px 0;font-family:'DM Sans',sans-serif;">
  <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;">
    <span style="font-family:'IBM Plex Mono',monospace;font-size:0.72rem;color:#8b5cf6;font-weight:700;letter-spacing:0.1em;">▸ VOLUME INTELLIGENCE · MnM</span>
    <span style="font-family:'IBM Plex Mono',monospace;font-size:0.72rem;color:{cc};background:{cc}22;border:1px solid {cc}55;border-radius:4px;padding:2px 6px;">ZONE CONF {cs}/10</span>
  </div>
  <div style="background:{vbg};border:1px solid {vc}33;border-radius:6px;padding:10px 12px;margin-bottom:10px;">
    <div style="font-size:0.8rem;color:{vc};font-weight:600;margin-bottom:4px;">{_sanitize_html_text(result.vol_type)}</div>
    <div style="font-size:0.72rem;color:{text_sub};">
      Frekuensi: <span style="color:{text_main};">{_sanitize_html_text(result.vol_freq_signal)}</span>
      {("&nbsp;&middot;&nbsp;<span style='color:#00e5a0;font-weight:600;'>✅ True Breakout Terkonfirmasi</span>") if result.breakout_valid else ""}
      {("&nbsp;&middot;&nbsp;<span style='color:#f23645;font-weight:600;'>⛔ False Breakout Terdeteksi</span>") if result.false_breakout else ""}
    </div>
  </div>
  <div style="margin-bottom:8px;">
    <div style="display:flex;justify-content:space-between;font-size:10px;color:{text_sub};font-family:'IBM Plex Mono',monospace;margin-bottom:3px;">
      <span>Vol Intelligence Score</span><span style="color:{vc};font-weight:600;">{vs}/100</span>
    </div>
    <div style="background:rgba(255,255,255,0.06);border-radius:3px;height:5px;">
      <div style="width:{vs}%;height:100%;background:{vc};border-radius:3px;transition:width 0.3s;"></div>
    </div>
  </div>
  <div>
    <div style="display:flex;justify-content:space-between;font-size:10px;color:{text_sub};font-family:'IBM Plex Mono',monospace;margin-bottom:3px;">
      <span>Akumulasi Score</span><span style="color:#00e5a0;font-weight:600;">{result.accum_score}/100</span>
    </div>
    <div style="background:rgba(255,255,255,0.06);border-radius:3px;height:5px;">
      <div style="width:{result.accum_score}%;height:100%;background:#00e5a0;border-radius:3px;"></div>
    </div>
  </div>
  {_zone_sigs_html}
</div>"""
    return html


# ─────────────────────────────────────────────
# ENRICH ROW (untuk tabel screener)
# ─────────────────────────────────────────────
def enrich_reco_row_with_zones(row: dict, zone_result: ZoneResult, C: dict) -> dict:
    """Tambah data zona ke dict baris tabel screener."""
    price = float(row.get("price", 0) or 0)
    row["zone_badge_html"] = zone_badge_html(zone_result, price, C)
    row["zone_conf"]       = zone_result.confluence_score
    row["zone_nearest"]    = zone_result.nearest_zone
    row["zone_vol_type"]   = zone_result.vol_type
    row["zone_accum"]      = zone_result.accum_score
    row["zone_breakout"]   = zone_result.breakout_valid
    row["zone_false_bo"]   = zone_result.false_breakout
    row["zone_signals"]    = zone_result.zone_signals

    # Adjust combined score
    conf_bonus  = zone_result.confluence_score * 0.5
    accum_bonus = max(0, (zone_result.accum_score - 50) * 0.1)
    bo_bonus    = 5 if zone_result.breakout_valid else 0
    bo_penalty  = -8 if zone_result.false_breakout else 0

    orig = float(row.get("combined", 50) or 50)
    row["combined"] = round(min(100, max(0, orig + conf_bonus + accum_bonus + bo_bonus + bo_penalty)), 1)
    return row


# ─────────────────────────────────────────────
# BATCH DETECT (untuk screener multi-ticker)
# ─────────────────────────────────────────────
def batch_detect_zones(tickers, max_workers=5) -> dict:
    """
    Deteksi zona untuk banyak ticker sekaligus.
    Gunakan st.cache_data(ttl=3600) saat dipanggil dari Streamlit.

    Returns: {ticker: ZoneResult}
    """
    import threading
    results = {}
    lock = threading.Lock()

    def fetch_one(tk):
        try:
            zr = detect_zones_multi_tf(tk)
        except Exception:
            zr = ZoneResult(ticker=tk)
        with lock:
            results[tk] = zr

    threads = []
    for tk in tickers:
        active = [t for t in threads if t.is_alive()]
        if len(active) >= max_workers:
            active[0].join(timeout=10)
        t = threading.Thread(target=fetch_one, args=(tk,), daemon=True)
        threads.append(t)
        t.start()

    for t in threads:
        t.join(timeout=15)

    return results


def add_zone_columns_to_rows(rows: list, C: dict) -> list:
    """
    Fetch & enrich semua row dari screener dengan data zona.
    Panggil sebelum generate HTML tabel.
    """
    if not rows: return rows
    tickers = tuple(sorted(set(r["ticker"] for r in rows if r.get("ticker"))))
    zone_map = batch_detect_zones(tickers)
    return [enrich_reco_row_with_zones(row, zone_map.get(row.get("ticker",""), ZoneResult()), C)
            for row in rows]


