# ─── FUNGSI API GEMINI ───
def _get_gemini_keys():
    """
    Auto-scan semua Gemini API key dari Secrets.
    Support: GEMINI_API_KEY, GEMINI_API_KEY2–5, GEMINI_KEY, GEMINI_KEY2–5, GOOGLE_API_KEY
    Tambah key baru di Secrets → langsung aktif tanpa edit kode.
    """
    key_names = (
        ["GEMINI_API_KEY"] +
        [f"GEMINI_API_KEY{i}" for i in range(2, 7)] +   # GEMINI_API_KEY2 s/d GEMINI_API_KEY6
        ["GEMINI_KEY"] +
        [f"GEMINI_KEY{i}" for i in range(2, 7)] +        # GEMINI_KEY2 s/d GEMINI_KEY6
        ["GOOGLE_API_KEY"]
    )
    keys = []
    for name in key_names:
        val = st.secrets.get(name, "")
        if val and len(val) > 10 and val not in keys:
            keys.append(val)
    return keys

def _call_gemini_vision(prompt, img_b64, img_mime, multi_imgs=None):
    """Gemini Vision - PRIMARY untuk semua request gambar. Auto-rotate key & model + backoff 429."""
    import urllib.request, json as _j
    all_keys = _get_gemini_keys()
    if not all_keys: raise Exception("Tidak ada Gemini API key yang valid di Secrets")
    keys = _get_available_gemini_keys(all_keys)
    models = ["gemini-2.5-flash", "gemini-2.0-flash"]
    last_err = ""
    for api_key in keys:
        if not _gemini_key_available(api_key):
            continue
        for model_name in models:
            try:
                _parts = []
                if multi_imgs:
                    for _b64, _mime, _ in multi_imgs[:5]: _parts.append({"inlineData": {"mimeType": _mime, "data": _b64}})
                elif img_b64 and img_mime: _parts.append({"inlineData": {"mimeType": img_mime, "data": img_b64}})
                teks_gabungan = f"{SYSTEM_PROMPT['content']}\n\n[PERTANYAAN USER]:\n{prompt}"
                _parts.append({"text": teks_gabungan})
                payload = {"contents": [{"role": "user", "parts": _parts}], "generationConfig": {"temperature": 0.7, "maxOutputTokens": 16384}}
                url = f"https://generativelanguage.googleapis.com/v1beta/models/{model_name}:generateContent?key={api_key}"
                req = urllib.request.Request(url, data=_j.dumps(payload).encode(), headers={"Content-Type": "application/json"})
                with urllib.request.urlopen(req, timeout=45) as r: data = _j.loads(r.read())
                return data["candidates"][0]["content"]["parts"][0]["text"], model_name
            except Exception as e:
                err_str = str(e)
                last_err = err_str
                if "429" in err_str or "quota" in err_str.lower() or "rate" in err_str.lower() or "exhausted" in err_str.lower():
                    _mark_gemini_key_ratelimited(api_key)
                    break  # skip ke key berikutnya
                continue
    raise Exception(f"Gemini Vision gagal semua model/key: {last_err}")

def _call_gemini_text(messages):
    """
    Gemini Text - FALLBACK untuk text jika semua Groq 70B rate limit.
    Auto-rotate 6 key + 2 model. Smart truncation ≤ 30.000 token.
    Exponential backoff per key saat 429.
    """
    import urllib.request, json as _j

    # Budget Gemini: context window besar (1M token), tapi kita batasi 30k agar respons cepat
    GEMINI_PROMPT_MAX_TOKENS = 24000  # sisakan ruang untuk system prompt + output

    all_keys = _get_gemini_keys()
    if not all_keys: raise Exception("Tidak ada Gemini API key yang valid di Secrets")
    # Prioritaskan key yang tidak sedang cooldown
    keys = _get_available_gemini_keys(all_keys)
    models = ["gemini-2.5-flash", "gemini-2.0-flash", "gemini-1.5-flash"]
    last_err = ""
    for api_key in keys:
        # Skip key yang sedang cooldown (double-check)
        if not _gemini_key_available(api_key):
            continue
        for model_name in models:
            try:
                gemini_contents = []
                for m in messages:
                    r = m.get("role", "")
                    t = m.get("content", "") or ""
                    # Bersihkan simbol AI dari history
                    t = re.sub(r'\n\n\*?\([✨⚡🤖].*?\)\*?', '', t)
                    # Truncate setiap pesan agar tidak membengkak
                    t = _smart_truncate_prompt(t, max_tokens=GEMINI_PROMPT_MAX_TOKENS // max(len(messages), 1))
                    if r == "user": gemini_contents.append({"role": "user", "parts": [{"text": t}]})
                    elif r == "assistant": gemini_contents.append({"role": "model", "parts": [{"text": t}]})
                if not gemini_contents: gemini_contents = [{"role": "user", "parts": [{"text": "Halo"}]}]
                # Inject system prompt ke pesan pertama
                sys_text = SYSTEM_PROMPT['content'] if isinstance(SYSTEM_PROMPT, dict) else str(SYSTEM_PROMPT)
                gemini_contents[0]["parts"][0]["text"] = f"{sys_text}\n\n{gemini_contents[0]['parts'][0]['text']}"
                payload = {
                    "contents": gemini_contents,
                    "generationConfig": {"temperature": 0.7, "maxOutputTokens": 16384}
                }
                url = f"https://generativelanguage.googleapis.com/v1beta/models/{model_name}:generateContent?key={api_key}"
                req = urllib.request.Request(url, data=_j.dumps(payload).encode(), headers={"Content-Type": "application/json"})
                with urllib.request.urlopen(req, timeout=35) as r: data = _j.loads(r.read())
                return data["candidates"][0]["content"]["parts"][0]["text"], model_name
            except Exception as e:
                err_str = str(e)
                last_err = err_str
                # 429 quota habis → tandai cooldown eksponensial + skip ke key berikutnya
                if "429" in err_str or "quota" in err_str.lower() or "rate" in err_str.lower() or "exhausted" in err_str.lower():
                    _mark_gemini_key_ratelimited(api_key)
                    break  # coba key berikutnya
                continue   # error lain → coba model berikutnya
    raise Exception(f"Gemini Text gagal semua model/key: {last_err}")

